using System.Text.Json.Nodes;
namespace GaevAssistant;
sealed class ProxySettings:Form {
 public ProxySettings(){Text="Прокси приложения";ClientSize=new(540,280);StartPosition=FormStartPosition.CenterParent;Font=new("Segoe UI",10);var panel=new TableLayoutPanel{Dock=DockStyle.Fill,Padding=new(20),ColumnCount=2,RowCount=5};panel.ColumnStyles.Add(new(SizeType.Absolute,140));panel.ColumnStyles.Add(new(SizeType.Percent,100));Controls.Add(panel);JsonObject config;try{config=Data.Secrets("network.dpapi");}catch{config=new();}var fields=new Dictionary<string,TextBox>();int n=0;foreach(var (key,label) in new[]{("address","Адрес http://…"),("username","Логин"),("password","Пароль")}){panel.RowStyles.Add(new(SizeType.Absolute,42));panel.Controls.Add(new Label{Text=label,AutoSize=true},0,n);var input=new TextBox{Text=Data.S(config,key),UseSystemPasswordChar=key=="password",Dock=DockStyle.Fill};fields[key]=input;panel.Controls.Add(input,1,n++);}var save=new Button{Text="Сохранить",AutoSize=true};panel.Controls.Add(save,1,3);save.Click+=(s,e)=>{if(!Uri.TryCreate(fields["address"].Text,UriKind.Absolute,out var u)||u.Scheme is not ("http" or "https")||u.UserInfo!=""){MessageBox.Show("Введите адрес прокси, например http://host:port. Логин и пароль указываются отдельно.");return;}foreach(var f in fields)config[f.Key]=f.Value.Text;Data.SaveSecrets("network.dpapi",config);Close();};panel.Controls.Add(new Label{Text="Применяется к API, WebSocket и записям ElevenLabs. Сохраняется зашифрованным для вашей учётной записи Windows.",AutoSize=true,MaximumSize=new(330,0)},1,4);}
